// ===== CONTENT RECYCLING DETECTOR =====
// Finds viral content that can be repurposed

const staticData = $getWorkflowStaticData('global');
const posts = staticData.posts || [];
const kb = staticData.knowledgeBase || {};

// Find posts worth recycling (high engagement)
const recyclablePosts = posts.filter(post => {
  const views = post.views || 0;
  const likes = post.likes || 0;
  const saves = post.saves || 0;
  const comments = post.comments || 0;

  // Viral threshold
  if (views > 10000) return true;
  // High engagement rate
  if (views > 0 && ((likes + saves + comments) / views) > 0.05) return true;
  // High saves (valuable content)
  if (saves > 100) return true;

  return false;
}).sort((a, b) => (b.views || 0) - (a.views || 0));

// Generate recycling ideas for each post
const recyclingPlans = recyclablePosts.slice(0, 5).map(post => {
  const formats = [
    {
      format: 'reel_script',
      title: '🎬 Reel Version',
      description: 'Turn this carousel into a talking-head or text-overlay reel',
      hook: post.hook,
      script: `[HOOK] ${post.hook}\n\n[CONTENT] Walk through the key points from the carousel\n\n[CTA] Follow for more!`,
      estimatedReach: 'Higher (reels get more reach)',
      effort: 'Medium'
    },
    {
      format: 'story_sequence',
      title: '📱 Story Version',
      description: 'Break into 5-7 story slides with polls/questions',
      slides: [
        `Story 1: "${post.hook}" (text overlay)`,
        'Story 2: Key point 1 + Poll sticker',
        'Story 3: Key point 2 + Question sticker',
        'Story 4: Key point 3 + Emoji slider',
        'Story 5: Key point 4 + Quiz sticker',
        'Story 6: Main takeaway',
        'Story 7: CTA + Link sticker'
      ],
      estimatedReach: 'Medium (story views)',
      effort: 'Low'
    },
    {
      format: 'quote_card',
      title: '💬 Quote Card',
      description: 'Extract the most impactful line as a standalone quote',
      quote: post.hook,
      design: 'Bold typography, brand colors, simple background',
      estimatedReach: 'Medium (shareable)',
      effort: 'Very Low'
    },
    {
      format: 'infographic',
      title: '📊 Infographic',
      description: 'Turn data points into a visual infographic',
      sections: ['Problem stats', 'Solution breakdown', 'Results data'],
      estimatedReach: 'High (saveable)',
      effort: 'Medium'
    },
    {
      format: 'thread',
      title: '🧵 Thread Version',
      description: 'Expand each slide into a detailed thread post',
      structure: 'Intro hook → Point 1-5 → Summary → CTA',
      estimatedReach: 'Medium-High',
      effort: 'Low'
    },
    {
      format: 'meme',
      title: '😂 Meme Version',
      description: 'Turn the core message into a relatable meme',
      template: 'Use trending meme format',
      estimatedReach: 'Very High (viral potential)',
      effort: 'Low'
    }
  ];

  return {
    originalPost: {
      id: post.id,
      hook: post.hook,
      views: post.views,
      engagement: (post.likes || 0) + (post.saves || 0) + (post.comments || 0)
    },
    recyclingFormats: formats,
    priority: post.views > 50000 ? 'HIGH' : post.views > 10000 ? 'MEDIUM' : 'LOW'
  };
});

return [{
  json: {
    recyclablePosts: recyclablePosts.length,
    recyclingPlans,
    chatId: staticData.chatId
  }
}];

// ===== SCHEDULE RECYCLED CONTENT =====
// Picks the best recycling format and schedules it

const input = $input.first().json;
const { recyclingPlans, chatId } = input;
const staticData = $getWorkflowStaticData('global');

// Pick the best recycling opportunity
const bestPlan = recyclingPlans[0];
if (!bestPlan) {
  return [{ json: { noRecycling: true, chatId } }];
}

// Pick the format with highest estimated reach
const formatPriority = ['meme', 'reel_script', 'infographic', 'thread', 'story_sequence', 'quote_card'];
const bestFormat = bestPlan.recyclingFormats.find(f => formatPriority.includes(f.format)) || bestPlan.recyclingFormats[0];

// Schedule the recycled content
const recycledContent = {
  originalId: bestPlan.originalPost.id,
  originalHook: bestPlan.originalPost.hook,
  newFormat: bestFormat.format,
  newTitle: bestFormat.title,
  content: bestFormat,
  scheduledTime: getNextPostTime(),
  status: 'scheduled'
};

// Store in recycling history
if (!staticData.recyclingHistory) staticData.recyclingHistory = [];
staticData.recyclingHistory.push({
  timestamp: new Date().toISOString(),
  ...recycledContent
});

function getNextPostTime() {
  // Schedule for next optimal posting time
  const now = new Date();
  const optimalHours = [9, 12, 17, 20]; // 9am, 12pm, 5pm, 8pm
  const currentHour = now.getHours();

  for (const hour of optimalHours) {
    if (hour > currentHour) {
      const scheduled = new Date(now);
      scheduled.setHours(hour, 0, 0, 0);
      return scheduled.toISOString();
    }
  }

  // Schedule for tomorrow 9am
  const tomorrow = new Date(now);
  tomorrow.setDate(tomorrow.getDate() + 1);
  tomorrow.setHours(9, 0, 0, 0);
  return tomorrow.toISOString();
}

return [{
  json: {
    recycledContent,
    totalRecyclable: recyclingPlans.length,
    chatId
  }
}];
